
:root{--ink:#ffe3bd;--or:#ff7a1a;--am:#ffb21a;--cy:#2fd8e8;--bg:#120805;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
*{box-sizing:border-box}html{scroll-padding-top:env(safe-area-inset-top,0px)}
body{margin:0;background:var(--bg);color:var(--ink);font-family:'Press Start 2P',monospace;font-size:9px}
nav{display:flex;gap:4px;flex-wrap:wrap;justify-content:center;padding:10px}
nav button{font:inherit;font-size:6.5px;background:#2a1208;color:var(--ink);border:2px solid var(--or);padding:6px 7px;cursor:pointer}
nav button.on{background:var(--or);color:#1a0d08}
.wrap{max-width:1000px;margin:0 auto;padding:0 8px 20px}
.stage{position:relative;aspect-ratio:16/9;background:#000;overflow:hidden;container-type:inline-size;border:3px solid var(--or);image-rendering:pixelated;user-select:none}
.scr{position:absolute;inset:0;display:none;background-size:100% 100%}.scr.on{display:block}
.L{background-image:url('data:image/png;base64,')}.T{background-image:url('data:image/png;base64,')}
.dim::before{content:"";position:absolute;inset:0;background:rgba(18,8,5,.58)}
.p{position:absolute;background-size:100% 100%;background-repeat:no-repeat;display:flex;align-items:center;justify-content:center;text-align:center;padding:2.2cqw 2.8cqw;line-height:1.8;font-size:1.05cqw;color:var(--ink)}
.i1{background-image:url('data:image/png;base64,')}.i2{background-image:url('data:image/png;base64,')}.i3{background-image:url('data:image/png;base64,')}.i4{background-image:url('data:image/png;base64,')}.i5{background-image:url('data:image/png;base64,')}.i6{background-image:url('data:image/png;base64,')}.i7{background-image:url('data:image/png;base64,')}.i8{background-image:url('data:image/png;base64,')}.i9{background-image:url('data:image/png;base64,')}.i10{background-image:url('data:image/png;base64,')}
.b{cursor:pointer;justify-content:flex-start;text-align:left;padding:0 1cqw 0 7cqw;font-size:1.1cqw}.b:hover,.ch:hover{filter:brightness(1.3)}
.b.s{padding-left:6cqw;font-size:.85cqw}.ch{cursor:pointer;padding:0}
.t{font-size:2.3cqw;color:var(--am);text-shadow:.25cqw .25cqw 0 #5a1d00;line-height:1.5}
.c{color:var(--cy)}.am{color:var(--am)}.sm{font-size:.9cqw}.ab{position:absolute}.col{flex-direction:column}.lf{text-align:left;align-items:flex-start}
.in{background:#2a0f05;border:.3cqw solid var(--or);color:var(--am);font:inherit;font-size:1.5cqw;width:16cqw;text-align:center;padding:.7cqw}
.bar{height:1.2cqw;background:#2a0f05;border:.2cqw solid var(--or);width:100%;margin-top:.5cqw}.bar i{display:block;height:100%;background:repeating-linear-gradient(90deg,var(--am) 0 .6cqw,#d9540a .6cqw .8cqw);transition:width .4s}
.circ{width:11.5cqw;height:11.5cqw;border-radius:50%;border:.5cqw solid var(--or);background:#2a0f05;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:.75cqw;text-align:center;line-height:1.6;gap:.5cqw;padding:1cqw}
.circ.f{box-shadow:0 0 0 .4cqw var(--am);border-color:var(--am)}.circ.pa{border-color:var(--cy)}.circ.n{opacity:.6}
.pin{position:absolute;width:2.4cqw;height:2.4cqw;background:var(--am);border:.3cqw solid #1a0d08;border-radius:50%;cursor:pointer;z-index:3;display:flex;align-items:center;justify-content:center;font-size:1.4cqw;color:#1a0d08}
.pin.lk{background:#555;cursor:default;opacity:.5}
.wire{position:absolute;width:4cqw;height:4cqw;cursor:pointer;border:.4cqw solid #1a0d08}
.slot{position:absolute;width:15cqw;height:7cqw;border:.35cqw dashed var(--am);background:rgba(42,15,5,.8);display:flex;align-items:center;justify-content:center;text-align:center;font-size:.75cqw;cursor:pointer;padding:.5cqw}.slot.ok{border-style:solid;background:#a8431a}
.tile{position:absolute;width:19cqw;height:9cqw;border:.35cqw solid var(--or);background:#2a0f05;cursor:pointer;font-size:.72cqw;padding:.8cqw;line-height:1.7}.tile.sel{border-color:var(--cy);box-shadow:0 0 0 .3cqw var(--cy)}.tile.dn{opacity:.3;pointer-events:none}
.msg{color:var(--am)}
input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:2cqw;background:#2a0f05;border:.3cqw solid var(--or)}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:3cqw;height:3.4cqw;background:var(--am);border:.3cqw solid #1a0d08;cursor:grab}
input[type=range]::-moz-range-thumb{width:3cqw;height:3.4cqw;background:var(--am);border:.3cqw solid #1a0d08;border-radius:0}
.fade{opacity:0;transition:opacity 1.2s}.fade.on{opacity:1}
.spr{position:absolute;image-rendering:pixelated;pointer-events:none}.nxt{z-index:7}#ty{pointer-events:auto;cursor:pointer}.wire{touch-action:none}
.p.btn2{padding:0!important}.btn2{overflow:visible}
.btn2 .lbl{position:absolute;top:0;bottom:0;display:flex;align-items:center;justify-content:center;white-space:nowrap;text-align:center;color:#ffe3bd;overflow:hidden;line-height:1;pointer-events:none;text-shadow:.15cqw .15cqw 0 #1a0d08}
.i7 .lbl{left:34%;right:11%;top:22%;bottom:30%}.i9 .lbl{left:28%;right:9%;top:23%;bottom:30%}.i8 .lbl{left:25%;right:11%;top:22%;bottom:26%}
.note{font-size:8px;line-height:2;margin:10px 0;color:#d9b68a}

